    <section class='card'>
      <h2><span class='num'>2</span> Claim details</h2>
      <div class='body'>
        <p class='hint' style='margin:0 0 14px'>Intake cannot open a file without this information, so every field in this step is required.</p>
        <div class='grid'>
          <div class='field' id='field-last-day-worked'>
            <label for='last-day-worked'>Last day worked <span class='req' aria-hidden='true'>*</span></label>
