            <span class='field-error' id='error-first-day-absent'>Enter the first day of the absence.</span>
          </div>
          <div class='field' id='field-nature-of-absence'>
            <label for='nature-of-absence'>Nature of absence <span class='req' aria-hidden='true'>*</span></label>
            <select id='nature-of-absence' name='nature-of-absence' required aria-required='true'>
              <option value=''>Select one</option>
              <option>Illness — non-occupational</option>
              <option>Injury — non-occupational</option>
              <option>Surgery and recovery</option>
              <option>Mental health</option>
              <option>Pregnancy or parental leave</option>
              <option>Other</option>
            </select>
            <span class='field-error' id='error-nature-of-absence'>Choose the nature of the absence.</span>
          </div>
          <div class='field wide' id='field-absence-details'>
            <label for='absence-details'>Details for intake <span class='req' aria-hidden='true'>*</span> <span class='hint'>(duties affected, expected return, accommodations attempted)</span></label>
            <textarea id='absence-details' name='absence-details' required aria-required='true' placeholder='Describe the absence, the duties affected and anything intake should know to open the file.'></textarea>
            <span class='field-error' id='error-absence-details'>Describe the absence so intake can open the file.</span>
          </div>
        </div>
        <div class='err-box' id='claim-error' role='alert'></div>
      </div>
    </section>

    <section class='card'>
      <h2><span class='num'>3</span> Supporting documents</h2>
      <div class='body'>
        <div class='field wide'>
          <label for='documents'>Attach documents <span class='hint'>(employer statement, attending physician statement, job description)</span></label>
          <input type='file' id='documents' name='documents' multiple accept='.pdf,.jpg,.jpeg,.png,.doc,.docx'>
          <p class='hint' style='margin:2px 0 0'>PDF, JPG, PNG, DOC or DOCX. Maximum 10 MB per file. Choose every document in one selection — a later selection replaces the packet rather than adding to it. Everything attached here travels as one packet under a single reference.</p>
        </div>
        <p class='empty' id='file-empty'>No documents attached yet.</p>
        <ul class='files' id='file-list'></ul>
        <div class='err-box' id='file-error' role='alert'></div>
      </div>
    </section>

    <section class='card'>
      <h2><span class='num'>4</span> Attestation</h2>
      <div class='body'>
        <div class='attest'>
          <input type='checkbox' id='attestation' name='attestation' required aria-required='true'>
          <label for='attestation'>I confirm that the member and plan details shown above, as pre-populated from the policy record, are accurate and complete to the best of my knowledge, that I have reported any discrepancy to my payroll team, and that I am authorised by the plan sponsor to submit this disability claim on the member&rsquo;s behalf.</label>
        </div>
        <div class='err-box' id='attest-error' role='alert'></div>
      </div>
    </section>

    <div class='actions'>
      <p class='note'>Submitting sends one associated packet to MapleSure intake and returns your reference immediately.</p>
      <button type='submit' class='btn btn-primary' id='submit-btn'>Submit claim</button>
    </div>
  </form>

  <section id='confirmation' hidden aria-live='polite'>
    <div class='conf-head'>
      <div class='tick'>&#10003;</div>
      <div>
        <h2>Claim submitted to MapleSure intake</h2>
        <p class='conf-sub' id='conf-sub'></p>
      </div>
    </div>

    <p style='margin:18px 0 0'><span class='staged' id='conf-staged-badge'>Staged &middot; demo output</span></p>
    <div class='staged-note' id='conf-staged-note'>This confirmation is <strong>staged demo output</strong>. Nothing is sent, stored or indexed: the reference number is generated in the browser, no record exists in any MapleSure system, and the status and next steps below describe how the live service would behave, not something that has happened.</div>

    <div class='ref'>
      <dl class='kv'>
        <div>
          <dt>Reference number</dt>
          <dd class='refno' id='reference-number'></dd>
        </div>
        <div>
          <dt>Status</dt>
